import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"这是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-it.md","filePath":"guide/what-is-it.md","lastUpdated":1787023323000}'),d={name:"guide/what-is-it.md"};function r(l,t,s,n,c,h){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h1><p><strong>AI Coding Kit</strong> 是一套面向 AI 辅助编程的方法论工具集，集中管理 <strong>Skills、Agents、Rules</strong> 三类资源，以 <a href="/ai-coding-kit/dev-flow/"><code>dev-flow</code></a> 工作流引擎为核心旗舰，构建从需求理解到代码交付的完整开发生命周期。</p><h2 id="为什么做" tabindex="-1">为什么做 <a class="header-anchor" href="#为什么做" aria-label="Permalink to &quot;为什么做&quot;">​</a></h2><p>AI 结对编程强大但也容易失控：猜测需求、过度重构、遗漏边界、延续老代码缺陷……本工具集把工程团队沉淀的最佳实践固化为<strong>可被 AI 直接加载执行的规范与流程</strong>，让 AI 编程既高效又可控。</p><p>核心解决三个问题：</p><ul><li><strong>流程无序</strong> → <code>dev-flow</code> 提供阶段 0 + 步骤 1~10 的系统化工作流，强制需求理解、根因定位、最小入侵。</li><li><strong>质量失守</strong> → Rules 红线 + 质量保障类 Skills（code-review / verification-* / security-review）守住工程底线。</li><li><strong>经验流失</strong> → 学习进化类 Skills（knowledge-loop / self-improving-agent）沉淀并复用代码知识。</li></ul><h2 id="三类资源" tabindex="-1">三类资源 <a class="header-anchor" href="#三类资源" aria-label="Permalink to &quot;三类资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>数量</th><th>作用</th></tr></thead><tbody><tr><td><a href="/ai-coding-kit/skills/">Skills</a></td><td>29 个</td><td>AI 技能定义，每个是独立目录含 <code>SKILL.md</code> 主文件</td></tr><tr><td><a href="/ai-coding-kit/rules/">Rules</a></td><td>16 条</td><td>编码规范与项目规则（<code>.mdc</code>），约束 AI 代码生成行为</td></tr><tr><td><a href="/ai-coding-kit/agents/">Agents</a></td><td>10 个</td><td>不同场景下的专职 Agent 配置</td></tr></tbody></table><h2 id="设计哲学-单一权威源" tabindex="-1">设计哲学：单一权威源 <a class="header-anchor" href="#设计哲学-单一权威源" aria-label="Permalink to &quot;设计哲学：单一权威源&quot;">​</a></h2><p>本文档站遵循 dev-flow 的核心哲学 —— <strong>单一权威源（Single Source of Truth）</strong>。</p><p>源文件始终保持原位（<code>skills/</code>、<code>rules/</code>、<code>agents/</code>），文档站通过<strong>构建时脚本</strong>把内容「投影」到站点，绝不复制维护第二份。这意味着：</p><ul><li>修改源文件后，重新生成即同步到文档站，无需手动同步两处。</li><li>文档与实际生效的规范永远一致，杜绝「文档说一套、代码做一套」。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想快速体验 → <a href="/ai-coding-kit/guide/quick-start">5 分钟快速上手</a></li><li>想了解安装细节 → <a href="/ai-coding-kit/guide/installation">安装与配置</a></li><li>想深入核心引擎 → <a href="/ai-coding-kit/dev-flow/">dev-flow 旗舰板块</a></li></ul>',14)])])}const f=e(d,[["render",r]]);export{u as __pageData,f as default};
